    {
      "indicator": "Preço (close)",
      "reading": "10.74",
      "interpretation": "Fechamento abaixo da MM20 (10.7970) e das EMAs; acima da MM50 (10.4784) e MM200 (9.0834) — pullback no curto prazo dentro de estrutura de alta."
    },
    {
      "indicator": "MM20",
      "reading": "10.7970",
      "interpretation": "Média curta acima da MM50 e MM200 (configuração de tendência altista). Preço atual ligeiramente abaixo -> correção de curtíssimo prazo."
    },
    {
      "indicator": "MM50",
      "reading": "10.4784",
      "interpretation": "Suporte de médio prazo; preço acima indica tendência de médio prazo ainda positiva enquanto for respeitado."
    },
    {
      "indicator": "MM200",
      "reading": "9.0834",
      "interpretation": "Suporte de longo prazo bem distante do preço atual — confirma viés de alta estrutural."
    },
    {
      "indicator": "EMA9",
      "reading": "10.8034",
      "interpretation": "EMA9 > EMA21 (tendência de curtíssimo prazo ainda inclinada), porém preço está abaixo da EMA9, apontando perda momentânea de impulso."
    },
    {
      "indicator": "EMA21",
      "reading": "10.7463",
      "interpretation": "Próxima ao preço; cruzamento EMA9>EMA21 favorece viés altista, mas confirmação depende de recuperação do preço acima dessas EMAs."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD 0.0929 / Signal 0.1210 / Hist -0.0281",
      "interpretation": "MACD positivo (tendência subjacente compradora) mas abaixo da linha de sinal e histograma negativo -> momentum de curtíssimo prazo enfraquecido."
    },
    {
      "indicator": "RSI14",
      "reading": "51.1349",
      "interpretation": "Neutro; sem condição clara de sobrecompra ou sobrevenda."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Lower 10.4486 / Mid 10.7970 / Upper 11.1454",
      "interpretation": "Preço entre média e banda inferior; volatilidade moderada e sem estiramento que indique movimento extremo."
    },
    {
      "indicator": "Volume (01-04-2024)",
      "reading": "4452900",
      "interpretation": "Volume do dia moderado; houve picos em março (ex.: 31.444.600 em 27/03) mas sem confirmação consistente de rompimento."
    }
  ]
